with tab_compare:
    st.markdown("## 🧪 Before vs after")
    st.write(
        "Measure whether a change actually reduced token usage. Save a baseline, apply a recommendation, "
        "then analyze a comparable follow-up session. Comparisons are only meaningful when the task, model, "
        "and workload are similar."
    )

    # Persistent local history: snapshots and comparison records are stored beside this app.
    HISTORY_PATH = Path(__file__).with_name("tokenluma_history.json")

    def _load_history():
        try:
            if HISTORY_PATH.exists():
                with HISTORY_PATH.open("r", encoding="utf-8") as handle:
                    data = json.load(handle)
                if isinstance(data, dict):
                    data.setdefault("snapshots", [])
                    data.setdefault("comparisons", [])
                    return data
        except (OSError, json.JSONDecodeError):
            st.warning("Could not read tokenluma_history.json. A fresh history will be used for this run.")
        return {"snapshots": [], "comparisons": []}

    def _save_history(data):
        try:
            with HISTORY_PATH.open("w", encoding="utf-8") as handle:
                json.dump(data, handle, indent=2)
            return True
        except OSError as exc:
            st.error(f"Could not save comparison history: {exc}")
            return False

    def _snapshot(label, totals, calls, estimated_cost):
        return {
            "id": datetime.now().strftime("%Y%m%d%H%M%S%f"),
            "saved_at": datetime.now().isoformat(timespec="seconds"),
            "label": label,
            "calls": int(totals.get("calls", 0)),
            "fresh_input": int(totals.get("fresh_input", 0)),
            "cache_read": int(totals.get("cache_read", 0)),
            "cache_write": int(totals.get("cache_write", 0)),
            "output": int(totals.get("output", 0)),
            "context_now": int(totals.get("context_now", 0)),
            "estimated_cost": float(estimated_cost),
            "session_file": str(selected_path),
        }

    history = _load_history()
    current_snapshot = _snapshot(Path(selected_path).name, totals, calls, estimated_cost)

    st.markdown("### 1. Save a run to history")
    if source_mode == "Demo mode (synthetic)":
        st.info("Demo Mode is for exploration only. Saving synthetic data to your persistent experiment history is disabled.")
    else:
        st.caption("Saved runs remain available after restarting the app. History is stored locally in tokenluma_history.json.")
        save_col, label_col = st.columns([1, 2])
        with label_col:
            run_note = st.text_input(
                "Experiment note (optional)",
                placeholder="e.g. Used targeted file reads instead of reading the whole repository",
                key="tokenluma_run_note",
            )
        with save_col:
            st.write("")
            st.write("")
            if st.button("💾 Save current run", type="primary", use_container_width=True):
                current_snapshot["note"] = run_note.strip()
                history["snapshots"].append(current_snapshot)
                if _save_history(history):
                    st.success("Run saved to persistent history.")
                    st.rerun()

    history = _load_history()
    snapshots = history.get("snapshots", [])
    if not snapshots:
        st.info("No saved runs yet. Save your current session, then save another session after trying an optimization.")
    else:
        snapshot_labels = {
            f"{s.get('saved_at', '')} · {s.get('label', 'Session')} · {s.get('note', '') or 'No note'} · ID {s.get('id', '')}": s
            for s in snapshots
        }
        label_list = list(snapshot_labels.keys())
        st.markdown("### 2. Compare any two saved runs")
        left, right = st.columns(2)
        with left:
            before_label = st.selectbox("Baseline run", label_list, index=0, key="tc_before_run")
        with right:
            after_default = len(label_list) - 1
            after_label = st.selectbox("Follow-up run", label_list, index=after_default, key="tc_after_run")

        before_run = snapshot_labels[before_label]
        after_run = snapshot_labels[after_label]

        if before_run.get("id") == after_run.get("id"):
            st.warning("Choose two different saved runs to compare.")
        else:
            metrics = [
                ("Fresh input", "fresh_input"),
                ("Cache reads", "cache_read"),
                ("Cache writes", "cache_write"),
                ("Output tokens", "output"),
                ("API calls", "calls"),
            ]
            compare_rows = []
            for label, key in metrics:
                before_value = int(before_run.get(key, 0))
                after_value = int(after_run.get(key, 0))
                delta = after_value - before_value
                pct = (delta / before_value * 100) if before_value else None
                compare_rows.append({
                    "Metric": label,
                    "Before": before_value,
                    "After": after_value,
                    "Change": delta,
                    "Change %": f"{pct:+.1f}%" if pct is not None else "N/A (baseline is 0)",
                })
            st.dataframe(pd.DataFrame(compare_rows), use_container_width=True, hide_index=True)

            before_activity = sum(int(before_run.get(k, 0)) for k in ("fresh_input", "cache_read", "cache_write", "output"))
            after_activity = sum(int(after_run.get(k, 0)) for k in ("fresh_input", "cache_read", "cache_write", "output"))
            delta_activity = after_activity - before_activity
            pct_activity = (delta_activity / before_activity * 100) if before_activity else None
            before_cost = float(before_run.get("estimated_cost", 0))
            after_cost = float(after_run.get("estimated_cost", 0))
            delta_cost = after_cost - before_cost
            pct_cost = (delta_cost / before_cost * 100) if before_cost else None

            m1, m2, m3 = st.columns(3)
            m1.metric(
                "Token activity change", f"{delta_activity:+,}",
                delta=f"{pct_activity:+.1f}%" if pct_activity is not None else "baseline is 0",
                delta_color="inverse",
                help="Sum of token categories for comparison; not a count of unique tokens."
            )
            m2.metric(
                "Estimated cost change", f"${delta_cost:+.4f}",
                delta=f"{pct_cost:+.1f}%" if pct_cost is not None else "baseline is 0",
                delta_color="inverse",
                help="Estimate saved with the prices configured at the time each run was saved."
            )
            m3.metric("Follow-up context", f"{int(after_run.get('context_now', 0)):,}")

            if before_activity and after_activity < before_activity:
                st.success(f"Token activity was {abs(delta_activity):,} lower ({abs(pct_activity):.1f}%) in the follow-up run.")
            elif before_activity and after_activity > before_activity:
                st.warning(f"Token activity was {delta_activity:,} higher ({pct_activity:.1f}%) in the follow-up run.")
            else:
                st.info("No token activity reduction is visible, or the baseline has no token activity.")

            if st.button("📚 Save this comparison to experiment history", use_container_width=True):
                record = {
                    "saved_at": datetime.now().isoformat(timespec="seconds"),
                    "before_id": before_run.get("id"),
                    "before_label": before_run.get("label"),
                    "before_note": before_run.get("note", ""),
                    "after_id": after_run.get("id"),
                    "after_label": after_run.get("label"),
                    "after_note": after_run.get("note", ""),
                    "token_activity_before": before_activity,
                    "token_activity_after": after_activity,
                    "token_activity_change": delta_activity,
                    "estimated_cost_before": before_cost,
                    "estimated_cost_after": after_cost,
                    "estimated_cost_change": delta_cost,
                }
                history["comparisons"].append(record)
                if _save_history(history):
                    st.success("Comparison added to persistent experiment history.")
                    st.rerun()

            export_rows = []
            for label, key in metrics:
                export_rows.append({
                    "Metric": label,
                    "Before": int(before_run.get(key, 0)),
                    "After": int(after_run.get(key, 0)),
                })
            st.download_button(
                "Download selected comparison (CSV)",
                pd.DataFrame(export_rows).to_csv(index=False).encode("utf-8"),
                file_name="tokenluma-before-after.csv",
                mime="text/csv",
            )

    history = _load_history()
    saved_comparisons = history.get("comparisons", [])
    saved_snapshots = history.get("snapshots", [])
    st.markdown("### 3. Experiment history")
    if saved_comparisons:
        display_rows = [{
            "Saved at": item.get("saved_at", ""),
            "Baseline": item.get("before_label", ""),
            "Baseline note": item.get("before_note", ""),
            "Follow-up": item.get("after_label", ""),
            "Follow-up note": item.get("after_note", ""),
            "Token activity change": item.get("token_activity_change", 0),
            "Estimated cost change ($)": round(float(item.get("estimated_cost_change", 0)), 4),
        } for item in saved_comparisons]
        st.dataframe(pd.DataFrame(display_rows), use_container_width=True, hide_index=True)
        st.download_button(
            "Export all experiment history (CSV)",
            pd.DataFrame(display_rows).to_csv(index=False).encode("utf-8"),
            file_name="tokenluma-experiment-history.csv",
            mime="text/csv",
        )
    else:
        st.caption("Your saved comparisons will appear here so you can track experiments over time.")

    if saved_snapshots or saved_comparisons:
        if st.button("🗑️ Clear saved experiment history", type="secondary"):
            st.session_state["tokenluma_confirm_clear_history"] = True
        if st.session_state.get("tokenluma_confirm_clear_history", False):
            st.warning("This permanently removes saved run snapshots and comparisons from tokenluma_history.json.")
            confirm_col, cancel_col = st.columns(2)
            with confirm_col:
                if st.button("Yes, clear history", type="primary", key="tokenluma_confirm_clear_yes"):
                    if _save_history({"snapshots": [], "comparisons": []}):
                        st.session_state["tokenluma_confirm_clear_history"] = False
                        st.rerun()
            with cancel_col:
                if st.button("Cancel", key="tokenluma_confirm_clear_cancel"):
                    st.session_state["tokenluma_confirm_clear_history"] = False
                    st.rerun()

    st.warning(
        "Interpret carefully: these are differences between sessions, not proof that a recommendation caused the change. "
        "Compare similar tasks, the same model, similar tool work, and similar cache conditions. "
        "Token activity sums categories and should not be treated as unique tokens or guaranteed savings. "
        "History is stored locally in tokenluma_history.json; keep that file with the app to retain it."
    )

with st.expander("How to read these numbers"):
    st.markdown(
        """
        - **Fresh input:** `input_tokens` summed across API calls.
        - **Cache writes:** `cache_creation_input_tokens` summed across calls.
        - **Cache reads:** `cache_read_input_tokens` summed across calls.
        - **Output:** `output_tokens` summed across calls; the source script notes this can include thinking tokens.
        - **Context:** input + cache-read + cache-creation tokens for a call.
        - **Context growth:** current context minus the previous call's context.
        - **Carry:** positive context growth multiplied by the number of later calls, used as a heuristic for repeated context cost.
        - **Cache miss:** earlier context that was not read from cache, as estimated by the existing TokenLuma logic.
        """
    )

